    AssociateVirtualInterfaceOutput.add_member(:mtu, Smithy::Schema::Shapes::ShapeRef.new(shape: MTU, location_name: 'mtu', traits: {"smithy.api#documentation" => "<p>The maximum transmission unit (MTU), in bytes. The supported values are 1500 and 8500. The default value is 1500</p>"}))
